GS_ADD([{"id":"a-lu-bill","reg":"Europe","mk":"LU","mkt":"Luxembourg","auth":"Ministry of Justice","cat":"Legislation","date":"2026-01-07","v":"official","t":"Luxembourg tables bill against illegal gambling in cafés","d":"Bill 8679 widens the definition of gambling and raises penalties. Online gambling is left for later.","b":["The justice minister tabled bill no. 8679 amending the gambling law of 1977. It widens the definition of gambling to cover cafés, private clubs and terminals disguised as internet access, and raises criminal penalties. It does not regulate online gambling, which the explanatory memorandum leaves to a later reform."],"src":[["Chambre des Députés, bill 8679 file (PDF)","https://wdocs-pub.chd.lu/docs/compilation/docpa/pdf/8679_Dossier_Complet.pdf","o"]],"archive":true,"es":{"mkt":"Luxemburgo","auth":"Ministerio de Justicia","t":"Luxemburgo presenta un proyecto de ley contra el juego ilegal en cafés","d":"El proyecto 8679 amplía la definición de juego y endurece las penas. El juego online queda para más adelante.","b":["El ministro de Justicia presentó el proyecto de ley n.º 8679, que modifica la ley del juego de 1977. Amplía la definición de juego para abarcar cafés, clubes privados y terminales camuflados como acceso a internet, y endurece las penas. No regula el juego online, que la exposición de motivos deja para una reforma posterior."]},"ru":{"mkt":"Люксембург","auth":"Министерство юстиции","t":"Люксембург внес законопроект против нелегальных азартных игр в кафе","d":"Законопроект 8679 расширяет определение азартных игр и ужесточает наказания. Онлайн-азартные игры оставлены на потом.","b":["Министр юстиции внес законопроект № 8679 о поправках к закону об азартных играх 1977 года. Он расширяет определение азартных игр, распространяя его на кафе, частные клубы и терминалы, замаскированные под доступ в интернет, и ужесточает уголовные наказания. Законопроект не регулирует онлайн-азартные игры: согласно пояснительной записке, это будет предметом последующей реформы."]}},{"id":"a-pl-tender","reg":"Europe","mk":"PL","mkt":"Poland","auth":"Ministry of Finance","cat":"Licensing","date":"2026-01-15","v":"official","t":"Poland changes casino and bingo tender rules","d":"Bidders now declare the tax base for three years, not six.","b":["A regulation of 23 December 2025 changes the tender rules for casino and bingo concessions from 15 January 2026. Bidders declare the gaming tax base for the first three years instead of the full six. Tender notices move to the Public Information Bulletin, and e-filing is allowed once the e-Koncesje system launches."],"src":[["Ministry of Finance","https://www.gov.pl/web/finanse/zmiana-rozporzadzenia-z-zakresu-gier-hazardowych","o"]],"archive":true,"es":{"mkt":"Polonia","auth":"Ministerio de Finanzas","t":"Polonia cambia las normas de los concursos de casinos y bingos","d":"Los licitadores declaran ahora la base imponible de tres años, no de seis.","b":["Un reglamento del 23 de diciembre de 2025 modifica desde el 15 de enero de 2026 las normas de los concursos de concesiones de casinos y bingos. Los licitadores declaran la base imponible del impuesto sobre el juego de los tres primeros años en lugar de los seis completos. Los anuncios de los concursos pasan al Boletín de Información Pública, y se permitirá la presentación electrónica cuando se ponga en marcha el sistema e-Koncesje."]},"ru":{"mkt":"Польша","auth":"Министерство финансов","t":"Польша изменила правила тендеров на казино и бинго","d":"Участники теперь декларируют налоговую базу на три года, а не на шесть.","b":["Постановление от 23 декабря 2025 года меняет правила тендеров на концессии казино и бинго с 15 января 2026 года. Участники декларируют базу налога на игорный бизнес за первые три года вместо полных шести. Объявления о тендерах переносятся в Бюллетень публичной информации. Электронная подача станет возможна после запуска системы e-Koncesje."]}},{"id":"a-za-20pc","reg":"Africa","mk":"ZA","mkt":"South Africa","auth":"National Treasury","cat":"Tax","date":"2026-01-15","v":"official","t":"South Africa extends consultation on 20% online gambling tax","d":"Treasury moved the comment deadline on its online gambling tax paper to 27 February 2026.","b":["National Treasury published a draft discussion paper on a national online gambling tax on 25 November 2025. It proposes a 20% tax on gross gambling revenue from online betting and interactive gambling, on top of the taxes provinces already charge.","Comments were first due by 30 January 2026. On 15 January Treasury said it had received many requests for more time and extended the deadline to 27 February 2026."],"src":[["National Treasury, deadline extension (gov.za)","https://www.gov.za/news/media-statements/treasury-extension-deadline-public-comments-respect-draft-national-online","o"],["National Treasury, publication statement (gov.za)","https://www.gov.za/news/media-statements/treasury-publication-draft-national-online-gambling-tax-discussion-paper-25","o"],["SAnews","https://www.sanews.gov.za/south-africa/government-proposes-20-online-gambling-tax","o"],["Focus Gaming News","https://focusgn.com/africa/south-africa-extends-consultation-on-proposed-online-gambling-tax","p"]],"archive":true,"es":{"mkt":"Sudáfrica","auth":"Tesoro Nacional","t":"Sudáfrica amplía la consulta pública sobre un impuesto del 20% al juego online","d":"El Tesoro trasladó al 27 de febrero de 2026 el plazo de comentarios sobre su documento relativo al impuesto al juego online.","b":["El Tesoro Nacional publicó el 25 de noviembre de 2025 un borrador de documento de debate sobre un impuesto nacional al juego online. Propone un impuesto del 20% sobre los ingresos brutos del juego de las apuestas online y el juego interactivo, además de los impuestos que ya cobran las provincias.","El plazo inicial para enviar comentarios vencía el 30 de enero de 2026. El 15 de enero el Tesoro informó de que había recibido muchas peticiones de más tiempo y amplió el plazo hasta el 27 de febrero de 2026."]},"ru":{"mkt":"ЮАР","auth":"National Treasury","t":"ЮАР продлила обсуждение налога в 20% на онлайн-азартные игры","d":"Национальное казначейство перенесло срок подачи замечаний по документу о налоге на онлайн-азартные игры на 27 февраля 2026 года.","b":["Национальное казначейство (National Treasury) 25 ноября 2025 года опубликовало проект документа для обсуждения о национальном налоге на онлайн-азартные игры. В нем предлагается налог в размере 20% с валового игорного дохода от онлайн-ставок и интерактивных азартных игр в дополнение к налогам, которые уже взимают провинции.","Первоначально замечания принимались до 30 января 2026 года. 15 января Казначейство сообщило, что получило много просьб о продлении срока, и перенесло его на 27 февраля 2026 года."]}},{"id":"a-eu-wunner","reg":"Europe","mk":"EU","mkt":"European Union","auth":"CJEU","cat":"Enforcement","date":"2026-01-15","v":"official","t":"EU court: player's home country is where losses from unlicensed gambling occur","d":"The Court of Justice ruled on claims against directors of operators that lacked a local licence. Damage is located where the player habitually lives.","b":["In case C-77/24 (Wunner), referred by Austria's Supreme Court, the Court of Justice interpreted the Rome II Regulation on the law that applies to non-contractual claims.","The court said a tort claim against company directors for offering games of chance without the required national licence does not fall under the company law exclusion in Rome II. Such claims are therefore covered by the regulation.","It also ruled that when a player sues over losses at an online operator that had no licence in that Member State, the damage occurs in the Member State where the player habitually resides. Under the regulation's general rule, that points to the law of the player's home country."],"src":[["CJEU, judgment C-77/24 (EUR-Lex)","https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=CELEX:62024CJ0077","o"],["CJEU, case file C-77/24","https://curia.europa.eu/juris/liste.jsf?num=C-77/24","o"],["European Lotteries, 21 Jan 2026","https://www.european-lotteries.org/news/cjeu-confirms-players-national-law-governs-illegal-online-gambling-claims","p"],["DLA Piper","https://www.dlapiper.com/en-be/insights/blogs/mse-today/2026/cjeu-clarifies-applicable-law-for-director-liability-in-cross-border-online-gambling-case","p"]],"archive":true,"es":{"mkt":"Unión Europea","auth":"TJUE","t":"Tribunal de la UE: las pérdidas del juego sin licencia se producen en el país del jugador","d":"El Tribunal de Justicia se pronunció sobre demandas contra administradores de operadores sin licencia local. El daño se sitúa donde el jugador tiene su residencia habitual.","b":["En el asunto C-77/24 (Wunner), planteado por el Tribunal Supremo de Austria, el Tribunal de Justicia interpretó el Reglamento Roma II sobre la ley aplicable a las obligaciones extracontractuales.","El tribunal señaló que una demanda por responsabilidad extracontractual contra los administradores de una empresa por ofrecer juegos de azar sin la licencia nacional exigida no entra en la exclusión del Derecho de sociedades del Reglamento Roma II. Por tanto, estas demandas quedan cubiertas por el reglamento.","También resolvió que, cuando un jugador reclama por pérdidas en un operador online que no tenía licencia en ese Estado miembro, el daño se produce en el Estado miembro donde el jugador reside habitualmente. Según la regla general del reglamento, eso remite a la ley del país de residencia del jugador."]},"ru":{"mkt":"Европейский союз","auth":"CJEU","t":"Суд ЕС: убытки от нелицензированных азартных игр возникают в стране проживания игрока","d":"Суд ЕС вынес решение по искам к директорам операторов, не имевших местной лицензии. Местом причинения ущерба признается место обычного проживания игрока.","b":["В деле C-77/24 (Wunner), переданном Верховным судом Австрии, Суд ЕС дал толкование Регламента Рим II о праве, применимом к внедоговорным обязательствам.","Суд указал, что деликтный иск к директорам компании за предложение азартных игр без необходимой национальной лицензии не подпадает под исключение для корпоративного права в Регламенте Рим II. Поэтому на такие иски распространяется действие регламента.","Суд также постановил, что если игрок предъявляет иск в связи с проигрышами у онлайн-оператора, не имевшего лицензии в данном государстве-члене, ущерб возникает в государстве-члене, где игрок обычно проживает. По общему правилу регламента это означает применение права страны проживания игрока."]}},{"id":"a-hu-poly","reg":"Europe","mk":"HU","mkt":"Hungary","auth":"SZTFH","cat":"Enforcement","date":"2026-01-16","v":"official","t":"Hungary adds Polymarket to its register of blocked gambling sites","d":"The gambling regulator's register lists polymarket.com and its subdomains as blocked.","b":["Hungary's Supervisory Authority for Regulated Activities (SZTFH) lists polymarket.com and base.polymarket.com, with their subdomains, in its public register of blocked gambling websites. The register names Adventure One QSS Inc. as the organiser of the prohibited gambling."],"src":[["SZTFH, register of blocked gambling websites","https://sztfh.hu/nyilvantartasok/szerencsejatekugyi-blokkolt-honlapok/","o"],["CMS","https://cms.law/en/hun/legal-updates/hungary-temporarily-blocks-access-to-polymarket-over-alleged-illegal-gambling","p"]],"archive":true,"es":{"mkt":"Hungría","auth":"SZTFH","t":"Hungría incluye Polymarket en su registro de sitios de juego bloqueados","d":"El registro del regulador del juego recoge polymarket.com y sus subdominios como bloqueados.","b":["La Autoridad de Supervisión de Actividades Reguladas de Hungría (SZTFH) incluye polymarket.com y base.polymarket.com, con sus subdominios, en su registro público de sitios web de juego bloqueados. El registro identifica a Adventure One QSS Inc. como organizador del juego prohibido."]},"ru":{"mkt":"Венгрия","auth":"SZTFH","t":"Венгрия внесла Polymarket в реестр заблокированных сайтов азартных игр","d":"В реестре регулятора азартных игр polymarket.com и его поддомены значатся как заблокированные.","b":["Венгерское Управление по надзору за регулируемой деятельностью (SZTFH) включило polymarket.com и base.polymarket.com с их поддоменами в публичный реестр заблокированных сайтов азартных игр. Организатором запрещенных азартных игр в реестре указана Adventure One QSS Inc."]}},{"id":"a-it-lotto","reg":"Europe","mk":"IT","mkt":"Italy","auth":"ADM","cat":"Licensing","date":"2026-01-22","v":"official","t":"ADM redraws the rules for the Lotto retail network","d":"Outlets collecting under €11,000 a year for two years running will lose their concession.","b":["An ADM director's determination of 20 January 2026 resets the rules for growing the Lotto collection network. Tobacconists can apply for a Lotto concession by 1 March each year.","New outlets per municipality are based on a reference of €110,000 in average yearly takings. In municipalities below that level, special assignments need at least 400 metres from the nearest outlet.","The minimum yearly collection is €11,000. From 2026, outlets below it in the last two years will be revoked by local ADM offices by 31 March, while keeping one or two outlets in each municipality depending on population."],"src":[["ADM, determination 39025 of 20 Jan 2026","https://www.adm.gov.it/portale/documents/20182/240768922/39025-20012026+ampliamento+rete+Lotto.pdf/95a2906e-3461-85f4-e424-c5ba13d92087?t=1769013811701","o"],["JAMMA","https://www.jamma.it/attualita/lotto-adm-cambia-le-regole-nuova-mappa-delle-ricevitorie-soglie-riviste-e-stretta-sullinefficienza-345649","p"]],"archive":true,"es":{"mkt":"Italia","auth":"ADM","t":"La ADM redefine las normas de la red de venta del Lotto","d":"Los puntos de venta que recauden menos de 11.000 euros al año durante dos años seguidos perderán la concesión.","b":["Una determinación de un director de la ADM del 20 de enero de 2026 redefine las normas para ampliar la red de recaudación del Lotto. Los estancos pueden solicitar una concesión de Lotto hasta el 1 de marzo de cada año.","El número de nuevos puntos de venta por municipio se calcula sobre una referencia de 110.000 euros de recaudación media anual. En los municipios por debajo de ese nivel, las asignaciones especiales exigen una distancia mínima de 400 metros al punto de venta más cercano.","La recaudación mínima anual es de 11.000 euros. A partir de 2026, las oficinas territoriales de la ADM revocarán antes del 31 de marzo los puntos de venta que no la hayan alcanzado en los dos últimos años, aunque se mantendrán uno o dos puntos por municipio según la población."]},"ru":{"mkt":"Италия","auth":"ADM","t":"ADM пересмотрело правила для розничной сети Lotto","d":"Точки, собирающие менее 11 000 евро в год два года подряд, лишатся концессии.","b":["Определение директора ADM от 20 января 2026 года обновляет правила развития сети приема ставок Lotto. Табачные киоски могут подавать заявки на концессию Lotto ежегодно до 1 марта.","Количество новых точек в муниципалитете рассчитывается исходя из ориентира в 110 000 евро среднегодовой выручки. В муниципалитетах ниже этого уровня для специальных назначений требуется расстояние не менее 400 метров до ближайшей точки.","Минимальный годовой сбор ставок составляет 11 000 евро. С 2026 года концессии точек, не достигших его в последние два года, будут отзываться местными отделениями ADM до 31 марта, при этом в каждом муниципалитете сохраняются одна или две точки в зависимости от численности населения."]}}]);
